import Toaster from "@marko-ui/shadcn/ui/toast/toast.marko";
import { toast } from "@marko-ui/shadcn/ui/toast/store.ts";

static function fetchData() {
  return new Promise<{ name: string }>((resolve) => {
    setTimeout(() => resolve({ name: "Toast" }), 2000);
  });
}

<button type="button"
  onClick() {
    toast.promise(fetchData, {
      loading: { title: "Loading..." },
      success: (data) => ({ title: `${data.name} toast has been added` }),
      error: { title: "Error" },
    });
  }
  class="border-input rounded-md border px-4 py-2 text-sm font-medium"
>
  Show Toast
</button>
<Toaster/>
